import { useState, useMemo } from "react";
import {
  DollarSign,
  Calendar,
  TrendingUp,
  Receipt,
  Trash2,
  UtensilsCrossed,
  Car,
  ShoppingBag,
  Zap,
  Film,
  HeartPulse,
  MoreHorizontal,
} from "lucide-react";

// ---- Category config: icon + color live in one place ----------------------
const CATEGORIES = {
  Food: { icon: UtensilsCrossed, color: "#F97316", bg: "#FFF1E6" },
  Transport: { icon: Car, color: "#3B82F6", bg: "#E8F0FE" },
  Shopping: { icon: ShoppingBag, color: "#A855F7", bg: "#F5EBFE" },
  Bills: { icon: Zap, color: "#EF4444", bg: "#FEECEC" },
  Entertainment: { icon: Film, color: "#EC4899", bg: "#FDEAF3" },
  Health: { icon: HeartPulse, color: "#10B981", bg: "#E7F8F1" },
  Other: { icon: MoreHorizontal, color: "#64748B", bg: "#EEF1F5" },
};

const todayISO = () => new Date().toISOString().split("T")[0];

const fmtMoney = (n) =>
  n.toLocaleString("en-US", { style: "currency", currency: "USD" });

const fmtDate = (iso) =>
  new Date(iso + "T00:00:00").toLocaleDateString("en-US", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });

export default function ExpenseTracker() {
  // In-memory store. Swap this for a real API/DB call if you wire one up.
  const [expenses, setExpenses] = useState([
    { id: 1, amount: 42.5, category: "Food", description: "Groceries", date: todayISO() },
    { id: 2, amount: 15, category: "Transport", description: "Metro card top-up", date: todayISO() },
  ]);

  const [form, setForm] = useState({
    amount: "",
    category: "",
    description: "",
    date: todayISO(),
  });
  const [error, setError] = useState("");

  // ---- Derived stats ----------------------------------------------------
  const stats = useMemo(() => {
    const now = new Date();
    const thisMonthKey = `${now.getFullYear()}-${now.getMonth()}`;

    const total = expenses.reduce((sum, e) => sum + e.amount, 0);

    const thisMonth = expenses
      .filter((e) => {
        const d = new Date(e.date + "T00:00:00");
        return `${d.getFullYear()}-${d.getMonth()}` === thisMonthKey;
      })
      .reduce((sum, e) => sum + e.amount, 0);

    const topCategoryEntry = Object.entries(
      expenses.reduce((acc, e) => {
        acc[e.category] = (acc[e.category] || 0) + e.amount;
        return acc;
      }, {})
    ).sort((a, b) => b[1] - a[1])[0];

    const dayOfMonth = now.getDate();
    const dailyAvg = thisMonth / dayOfMonth;

    return {
      total,
      thisMonth,
      topCategory: topCategoryEntry ? topCategoryEntry[0] : "—",
      dailyAvg,
      count: expenses.length,
    };
  }, [expenses]);

  // ---- Handlers -----------------------------------------------------------
  const handleChange = (field) => (e) =>
    setForm((f) => ({ ...f, [field]: e.target.value }));

  const handleSubmit = (e) => {
    e.preventDefault();
    const amountNum = parseFloat(form.amount);

    if (!form.amount || isNaN(amountNum) || amountNum <= 0) {
      setError("Enter a valid amount greater than 0.");
      return;
    }
    if (!form.category) {
      setError("Pick a category.");
      return;
    }
    if (!form.description.trim()) {
      setError("Add a short description.");
      return;
    }

    setExpenses((prev) => [
      {
        id: Date.now(),
        amount: amountNum,
        category: form.category,
        description: form.description.trim(),
        date: form.date,
      },
      ...prev,
    ]);

    setForm({ amount: "", category: "", description: "", date: todayISO() });
    setError("");
  };

  const handleDelete = (id) =>
    setExpenses((prev) => prev.filter((e) => e.id !== id));

  // ---- UI -----------------------------------------------------------------
  return (
    <div className="tracker-page">
      <div className="tracker-container">
        {/* Header */}
        <header className="tracker-header">
          <h1 className="tracker-title">Expense Tracker</h1>
          <p className="tracker-subtitle">
            Keep track of your spending and manage your budget
          </p>
        </header>

        {/* Stat cards */}
        <div className="stats-grid">
          <StatCard
            label="Total Expense"
            value={fmtMoney(stats.total)}
            icon={DollarSign}
            accent="#0D9488"
          />
          <StatCard
            label="This Month"
            value={fmtMoney(stats.thisMonth)}
            icon={Calendar}
            accent="#4F46E5"
          />
          <StatCard
            label="Top Category"
            value={stats.topCategory}
            icon={TrendingUp}
            accent="#F97316"
          />
          <StatCard
            label="Daily Average"
            value={fmtMoney(stats.dailyAvg || 0)}
            icon={Receipt}
            accent="#EC4899"
          />
        </div>

        {/* Main content */}
        <div className="main-grid">
          {/* Add expense form */}
          <section className="card">
            <h2 className="card-title">Add New Expense</h2>

            <form onSubmit={handleSubmit} className="expense-form">
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Amount ($)</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    placeholder="0.00"
                    value={form.amount}
                    onChange={handleChange("amount")}
                    className="form-input"
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Category</label>
                  <select
                    value={form.category}
                    onChange={handleChange("category")}
                    className="form-input"
                  >
                    <option value="">Select category</option>
                    {Object.keys(CATEGORIES).map((c) => (
                      <option key={c} value={c}>
                        {c}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Description</label>
                <input
                  type="text"
                  placeholder="What did you spend on?"
                  value={form.description}
                  onChange={handleChange("description")}
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label className="form-label">Date</label>
                <input
                  type="date"
                  value={form.date}
                  onChange={handleChange("date")}
                  className="form-input"
                />
              </div>

              {error && <p className="form-error">{error}</p>}

              <button type="submit" className="submit-btn">
                Add Expense
              </button>
            </form>
          </section>

          {/* Recent expenses */}
          <section className="card">
            <h2 className="card-title">Recent Expenses</h2>

            {expenses.length === 0 ? (
              <div className="empty-state">
                <Receipt size={40} className="empty-icon" />
                <p>No expenses yet. Add your first expense above!</p>
              </div>
            ) : (
              <ul className="expense-list">
                {expenses.map((e) => {
                  const cat = CATEGORIES[e.category] || CATEGORIES.Other;
                  const Icon = cat.icon;
                  return (
                    <li key={e.id} className="expense-item">
                      <div className="expense-item-left">
                        <span
                          className="expense-icon"
                          style={{ backgroundColor: cat.bg }}
                        >
                          <Icon size={18} color={cat.color} />
                        </span>
                        <div className="expense-info">
                          <p className="expense-desc">{e.description}</p>
                          <p className="expense-meta">
                            {e.category} · {fmtDate(e.date)}
                          </p>
                        </div>
                      </div>

                      <div className="expense-item-right">
                        <span className="expense-amount">
                          {fmtMoney(e.amount)}
                        </span>
                        <button
                          onClick={() => handleDelete(e.id)}
                          className="delete-btn"
                          aria-label={`Delete ${e.description}`}
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </li>
                  );
                })}
              </ul>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}

function StatCard({ label, value, icon: Icon, accent }) {
  return (
    <div className="stat-card">
      <div>
        <p className="stat-label">{label}</p>
        <p className="stat-value">{value}</p>
      </div>
      <span
        className="stat-icon"
        style={{ backgroundColor: `${accent}1A` }}
      >
        <Icon size={20} color={accent} />
      </span>
    </div>
  );
}
